/**
 * 编程流程插件（bundled，2026-08-16）：
 * - coding_plan：编程任务先出结构化计划（编号任务树/动词开头/边界/状态标记/验证段/紧凑），再动手
 * - coding_review：交付前过代码审查清单（安全扫描/质量门/自查点），改完自证没改坏
 *
 * 依赖 ctx：无特殊依赖（纯流程引导，实际执行用宿主自带 Read/Write/Edit/Grep/Typecheck 等工具）。
 * 输出结构遵循既定编程模式：思考后台化、输出编号任务树计划。
 */

/** 结构化任务计划框架（AI 填充具体内容） */
const codingPlan = {
  name: 'coding_plan',
  description: `生成结构化编程任务计划框架（先计划后动手，避免边想边改）。

何时用：
- 接到编程/改代码任务，动手前先出计划（尤其多文件、多步骤任务）
- 用户要求"先给计划"或任务复杂需要拆解

返回：计划框架（编号任务树 + 边界 + 验证段），你按此填充具体内容后执行。
结构约定（结构化）：
- 编号任务树：1. 2. 3.（子任务 1.1 1.2）——动词开头（分析/实现/验证/重构）
- 边界：明确做/不做（不做的事写清楚，避免越界）
- 状态标记：每个任务标注 [待办]/[进行中]/[完成]
- 验证段：每个任务配验证方式（typecheck/测试/行为断言）
- 紧凑：不废话，一行一个任务

执行纪律：
- 按计划顺序执行，完成一个勾一个（状态标记更新）
- 执行中发现计划有误 → 更新计划再继续（计划是活的，但变更要显式）
- 全部完成后用 coding_review 自查一遍再交付`,
  parameters: [
    { name: 'task', type: 'string', description: '任务描述（用户需求/要改什么）', required: true }
  ],
  async execute(params) {
    const task = String(params.task ?? '').trim()
    if (!task) return { ok: false, error: 'task 参数必填（任务描述）' }
    const plan = [
      `# 编程任务计划（结构化任务树）`,
      ``,
      `**任务**：${task}`,
      ``,
      `**边界**：`,
      `- 做：`,
      `- 不做：`,
      ``,
      `**任务树**（动词开头，标注状态）：`,
      `1. [待办] 分析 —— 读相关文件，确认改动面（涉及文件/依赖/调用链）`,
      `2. [待办] 计划细节 —— 拆分子任务、定验证方式`,
      `3. [待办] 实现 —— 按子任务逐项改（每项完成更新状态）`,
      `4. [待办] 验证 —— typecheck/测试/行为断言，确认没改坏`,
      `5. [待办] 收尾 —— 自查（coding_review）+ 汇报`,
      ``,
      `**验证段**：`,
      `- 每步实现后：跑 typecheck + 相关测试`,
      `- 交付前：coding_review 过一遍`,
      ``,
      `按此框架填充具体内容后执行，完成一项更新一项状态标记。`
    ].join('\n')
    return { ok: true, data: { plan, message: '计划框架已生成，请填充具体任务/边界/验证方式后按序执行（完成一项更新状态标记）。' } }
  }
}

/** 代码审查清单 */
const codingReview = {
  name: 'coding_review',
  description: `代码审查清单：交付前过一遍自查（安全/质量/回归），改完自证没改坏。

何时用：
- 完成编程任务、交付改动前
- 改完代码准备汇报时（先自查再交付）

参数：
- scope（可选）：审查范围描述（改了哪些文件/功能）；不传 = 全量自查当前改动

审查点（逐项过）：
1. 安全：无硬编码凭据/密钥；无危险命令注入；文件路径无穿越
2. 完整性：改动是否覆盖任务树全部条目（无漏项）；未做的是否已声明
3. 回归：typecheck 过；相关测试过；改了 UI 用 ui_snapshot(baseline/verify) 对比
4. 一致性：命名/风格与周边代码一致；注释无外部软件名纹身；无死代码残留
5. 注释规范：写注释必须说清这段代码为什么存在（动机）、什么作用（职责）、需要留存的理由；经全面检查判定无需留存的代码直接删除，不保留"留着可能有用"的死代码
6. 文档：接口/配置变化是否更新了对应文档

返回：审查清单逐项检查结果。`,
  parameters: [
    { name: 'scope', type: 'string', description: '审查范围（可选，如 "改了 SettingsPanel.tsx + registry.ts"）', required: false }
  ],
  async execute(params) {
    const scope = String(params.scope ?? '').trim()
    const checklist = [
      `# 代码审查清单（${scope ? `范围：${scope}` : '全量自查'}）`,
      ``,
      `1. **安全**：`,
      `   - [ ] 无硬编码凭据/密钥`,
      `   - [ ] 无危险命令注入/路径穿越`,
      `2. **完整性**：`,
      `   - [ ] 任务树全部条目完成（无漏项）`,
      `   - [ ] 未做的部分已显式声明（边界）`,
      `3. **回归**：`,
      `   - [ ] typecheck 通过`,
      `   - [ ] 相关测试通过`,
      `   - [ ] UI 改动：ui_snapshot baseline/verify 对比确认只改目标区域`,
`4. **一致性**：`,
      `   - [ ] 命名/风格与周边一致`,
      `   - [ ] 无死代码残留、无外部软件名纹身注释`,
      `5. **注释规范**：`,
      `   - [ ] 注释说清为什么存在（动机）/什么作用（职责）/留存理由`,
      `   - [ ] 判定无需留存的代码已删除（无"留着可能有用"死代码）`,
      `6. **文档**：`,
      `   - [ ] 接口/配置变化已更新对应文档`,
      ``,
      `逐项勾选并给出证据（命令输出/测试结果），全部通过才交付；有不过的 → 修复后重查。`
    ].join('\n')
    return { ok: true, data: { checklist, message: '审查清单已生成，逐项自查并给出证据（typecheck/测试输出），全部通过再交付。' } }
  }
}

export default [codingPlan, codingReview]
